from jsonb_to_recordset($q$[{"id":3239,"materia":"pcd","nivel":0,"enunciado":"A Língua Brasileira de Sinais é conhecida pela sigla:","opcoes":["Libras","LBS","Brasilsinal","Sinalbra"],"explicacao":"Reconhecida pela Lei 10.436/2002."},{"id":3240,"materia":"pcd","nivel":0,"enunciado":"O sistema de escrita em relevo usado por pessoas cegas é o:","opcoes":["Braille","Código Morse","Libras","Tadoma"],"explicacao":"Criado por Louis Braille no século XIX."},{"id":3241,"materia":"pcd","nivel":0,"enunciado":"Rampas, elevadores e banheiros adaptados são exemplos de medidas de:","opcoes":["Acessibilidade","Segurança patrimonial","Economia de energia","Controle de acesso"],"explicacao":"Garantem uso dos espaços com autonomia."},{"id":3242,"materia":"pcd","nivel":1,"enunciado":"Na LBI, tecnologia assistiva (ou ajuda técnica) abrange:","opcoes":["Produtos, equipamentos, métodos e serviços que promovam autonomia e participação","Apenas cadeiras de rodas fornecidas pelo SUS","Somente softwares de leitura de tela instalados em computadores do governo","Apenas próteses e órteses"],"explicacao":"Art. 3º, III da Lei 13.146/2015."},{"id":3243,"materia":"pcd","nivel":1,"enunciado":"Pela Lei 8.112/1990, os concursos públicos podem reservar às pessoas com deficiência até:","opcoes":["20% das vagas","5% das vagas","10% das vagas","50% das vagas"],"explicacao":"Art. 5º, § 2º. Decretos fixam o mínimo de 5%."},{"id":3244,"materia":"pcd","nivel":2,"enunciado":"Pela LBI, as escolas particulares, ao matricular aluno com deficiência:","opcoes":["Não podem cobrar valores adicionais pelas adaptações necessárias","Podem cobrar taxa extra proporcional ao custo","Podem recusar a matrícula se não houver vaga especial reservada na turma","Devem exigir laudo renovado a cada semestre"],"explicacao":"Art. 28, § 1º da Lei 13.146/2015."},{"id":3245,"materia":"pcd","nivel":2,"enunciado":"Pela LBI, os planos de saúde, em razão da deficiência do usuário:","opcoes":["Não podem cobrar valores diferenciados","Podem cobrar o dobro da mensalidade","Podem negar a contratação","Podem limitar consultas a seis por ano"],"explicacao":"Art. 23 da Lei 13.146/2015."},{"id":3246,"materia":"pcd","nivel":2,"enunciado":"A Lei 14.126/2021 classificou a visão monocular como:","opcoes":["Deficiência sensorial, do tipo visual","Doença ocupacional","Condição sem efeito jurídico","Deficiência física temporária, sem direito a cotas"],"explicacao":"Garante às pessoas com visão monocular os direitos da pessoa com deficiência."},{"id":3247,"materia":"pcd","nivel":2,"enunciado":"Segundo a Lei 7.853/1989, nas ações que discutam interesses relacionados à deficiência, o Ministério Público:","opcoes":["Intervirá obrigatoriamente","Só atua se o juiz pedir","Não pode intervir","Atua apenas em ações penais"],"explicacao":"Art. 5º da Lei 7.853/1989."},{"id":3248,"materia":"pcd","nivel":2,"enunciado":"A Lei 10.098/2000 determina que semáforos para pedestres em vias de tráfego intenso tenham:","opcoes":["Mecanismo de sinal sonoro como guia para pessoas cegas","Tempo fixo de 2 minutos para a travessia de pedestres idosos","Faixa exclusiva para cadeirantes","Botão acionado só por cartão especial"],"explicacao":"Art. 9º da Lei 10.098/2000."},{"id":3249,"materia":"pcd","nivel":2,"enunciado":"Pela LBI, o profissional de apoio escolar é aquele que:","opcoes":["Auxilia o estudante com deficiência na alimentação, higiene e locomoção na escola","Substitui o professor regente da turma quando o aluno não acompanha o conteúdo","Aplica provas diferentes para o aluno","Faz o diagnóstico da deficiência"],"explicacao":"Art. 3º, XIII; não exerce funções de professor."},{"id":3250,"materia":"pcd","nivel":3,"enunciado":"No Decreto 3.298/1999 (com redação do Decreto 5.296/2004), deficiência auditiva é a perda bilateral, parcial ou total, de:","opcoes":["41 decibéis ou mais","20 decibéis ou mais","60 decibéis ou mais","90 decibéis ou mais"],"explicacao":"Aferida por audiograma nas frequências indicadas no decreto."},{"id":3251,"materia":"pcd","nivel":3,"enunciado":"Pela LBI, apropriar-se de bens, pensão ou rendimentos da pessoa com deficiência é crime punido com:","opcoes":["Reclusão de 1 a 4 anos e multa","Detenção de 15 dias a 2 meses, convertida em multa","Apenas multa","Reclusão de 4 a 10 anos"],"explicacao":"Art. 89 da Lei 13.146/2015."},{"id":3252,"materia":"pcd","nivel":3,"enunciado":"A Lei 10.098/2000 exige que os parques de diversões adaptem, de cada brinquedo e equipamento, no mínimo:","opcoes":["5%, sendo pelo menos um","1% do total, sem mínimo garantido","20%","Metade"],"explicacao":"Art. 4º, parágrafo único, incluído pela Lei 11.982/2009."},{"id":3253,"materia":"pcd","nivel":3,"enunciado":"Pela LBI, as locadoras de veículos devem oferecer veículo adaptado na proporção de:","opcoes":["Um a cada 20 veículos da frota","Um a cada 100 veículos","Metade da frota","Um por filial, se houver pedido"],"explicacao":"Art. 52 da Lei 13.146/2015."},{"id":3254,"materia":"pcd","nivel":3,"enunciado":"Pela LBI, os táxis acessíveis devem corresponder a, no mínimo:","opcoes":["10% da frota","2% da frota","25% da frota","50% da frota"],"explicacao":"Art. 51 da Lei 13.146/2015."},{"id":3255,"materia":"pcd","nivel":4,"enunciado":"Segundo a LBI, a curatela NÃO alcança, entre outros, o direito:","opcoes":["Ao voto","De celebrar contratos de compra e venda","De administrar bens","De dar quitação de dívidas"],"explicacao":"Art. 85, § 1º: não alcança corpo, sexualidade, matrimônio, privacidade, educação, saúde, trabalho e voto."},{"id":3256,"materia":"pcd","nivel":4,"enunciado":"Na tomada de decisão apoiada, havendo divergência entre a pessoa apoiada e um dos apoiadores em negócio que traga risco relevante:","opcoes":["O juiz decide, ouvido o Ministério Público","Prevalece sempre a vontade do apoiador mais velho","O negócio é automaticamente nulo","A decisão cabe ao cartório"],"explicacao":"Art. 1.783-A, § 6º do Código Civil."},{"id":3257,"materia":"pcd","nivel":4,"enunciado":"Pela LBI, a pessoa com deficiência tem direito a atendimento prioritário, EXCETO quanto a:","opcoes":["Ser dispensada de cumprir prazos processuais","Restituição do imposto de renda","Tramitação de processos judiciais","Acesso a informações e comunicação"],"explicacao":"Art. 9º: prioridade não significa dispensa de prazos."},{"id":3258,"materia":"ia","nivel":0,"enunciado":"A sigla IA significa:","opcoes":["Inteligência artificial","Integração automática de dados","Internet avançada","Interface aplicada"],"explicacao":"Em inglês, AI (artificial intelligence)."},{"id":3259,"materia":"ia","nivel":0,"enunciado":"O texto que o usuário escreve para pedir algo a um assistente de IA é chamado de:","opcoes":["Prompt","Cookie","Firewall","Backup"],"explicacao":"Prompts mais claros tendem a gerar respostas melhores."},{"id":3260,"materia":"ia","nivel":0,"enunciado":"Vídeos falsos que imitam o rosto e a voz de pessoas reais, criados com IA, são chamados de:","opcoes":["Deepfakes","Spams","Cookies de rastreamento","Plugins"],"explicacao":"Um dos riscos de desinformação da IA generativa."},{"id":3261,"materia":"ia","nivel":0,"enunciado":"Um chatbot é um programa que:","opcoes":["Conversa com o usuário por mensagens","Protege a rede contra vírus","Faz cópia de segurança dos arquivos do usuário","Aumenta a velocidade da internet"],"explicacao":"Muitos usam modelos de linguagem."},{"id":3262,"materia":"ia","nivel":1,"enunciado":"Aprendizado de máquina (machine learning) é a área da IA em que o sistema:","opcoes":["Aprende padrões a partir de dados, sem ser programado regra a regra","Funciona apenas com regras fixas escritas à mão pelo programador responsável","Dispensa qualquer dado para funcionar","Serve apenas para jogos eletrônicos"],"explicacao":"Base de quase toda a IA moderna."},{"id":3263,"materia":"ia","nivel":1,"enunciado":"No aprendizado supervisionado, o modelo é treinado com:","opcoes":["Dados rotulados, em que a resposta certa é conhecida","Dados sem nenhum rótulo","Recompensas e punições recebidas em um ambiente simulado","Apenas imagens em preto e branco"],"explicacao":"No não supervisionado não há rótulos; no por reforço, há recompensas."},{"id":3264,"materia":"ia","nivel":2,"enunciado":"O aprendizado por reforço se caracteriza por:","opcoes":["Um agente que aprende por tentativa e erro, recebendo recompensas","Agrupar dados sem rótulo em categorias parecidas, sem nenhuma recompensa","Copiar respostas de um banco fixo","Treinar só com textos jurídicos"],"explicacao":"Usado, por exemplo, em jogos e robótica."},{"id":3265,"materia":"ia","nivel":2,"enunciado":"Deep learning (aprendizado profundo) usa principalmente:","opcoes":["Redes neurais artificiais com muitas camadas","Planilhas eletrônicas com fórmulas","Árvores genealógicas","Bancos de dados relacionais"],"explicacao":"É a base dos modelos de linguagem e de visão computacional."},{"id":3266,"materia":"ia","nivel":2,"enunciado":"A técnica RAG (geração aumentada por recuperação) consiste em:","opcoes":["Buscar documentos em uma base e usá-los para fundamentar a resposta do modelo","Apagar dados antigos do modelo","Treinar o modelo do zero a cada pergunta","Traduzir automaticamente o prompt para o inglês antes de enviar ao modelo"],"explicacao":"Reduz alucinações ao ancorar a resposta em fontes."},{"id":3267,"materia":"ia","nivel":2,"enunciado":"A expressão 'humano no circuito' (human in the loop) significa que:","opcoes":["Uma pessoa supervisiona e pode revisar as decisões do sistema de IA","O sistema funciona sem qualquer pessoa","Só humanos podem treinar o modelo","O usuário precisa digitar cada resposta que o sistema vai apresentar"],"explicacao":"Princípio central no uso de IA no Judiciário."},{"id":3268,"materia":"ia","nivel":2,"enunciado":"Treinar modelos de IA com obras protegidas sem autorização pode gerar risco de:","opcoes":["Violação de direitos autorais","Perda de garantia do computador","Queda de energia","Aumento do imposto de renda"],"explicacao":"Tema citado no edital entre os riscos da IA generativa."},{"id":3269,"materia":"ia","nivel":2,"enunciado":"Pela Resolução CNJ 395/2021, é princípio da gestão da inovação no Judiciário:","opcoes":["Foco no usuário","Sigilo absoluto dos projetos","Centralização das decisões no CNJ","Exclusividade de fornecedores"],"explicacao":"Também cultura da inovação, colaboração, acessibilidade e transparência."},{"id":3270,"materia":"ia","nivel":3,"enunciado":"O MVP (produto mínimo viável) é usado em inovação para:","opcoes":["Lançar uma versão simples da solução e aprender com o uso real","Adiar o lançamento até a solução ficar perfeita e sem nenhum erro","Calcular o valor de mercado do produto","Registrar a solução em cartório"],"explicacao":"Conceito da metodologia lean startup."},{"id":3271,"materia":"ia","nivel":3,"enunciado":"No modelo 'duplo diamante' de design, cada diamante representa um movimento de:","opcoes":["Divergir (abrir opções) e depois convergir (escolher)","Comprar e depois vender","Planejar e depois arquivar","Programar e depois testar o hardware"],"explicacao":"O primeiro diamante explora o problema; o segundo, a solução."},{"id":3272,"materia":"ia","nivel":3,"enunciado":"A inovação disruptiva se diferencia da incremental porque:","opcoes":["Muda profundamente o modo de fazer, criando algo novo","Faz pequenas melhorias no que já existe","Não usa tecnologia","Só ocorre em empresas privadas"],"explicacao":"A incremental aperfeiçoa processos e produtos existentes."},{"id":3273,"materia":"ia","nivel":3,"enunciado":"A explicabilidade de um sistema de IA diz respeito à capacidade de:","opcoes":["Compreender e justificar como o sistema chegou a um resultado","Funcionar sem conexão com a internet","Responder em vários idiomas","Rodar em computadores antigos"],"explicacao":"Importante para transparência e controle de decisões."},{"id":3274,"materia":"ia","nivel":4,"enunciado":"Segundo a Resolução CNJ 332/2020, o usuário externo deve ser informado de que:","opcoes":["O sistema usa IA, de forma clara, e de que as propostas não são vinculantes","O sistema nunca erra","Não pode recorrer de decisões apoiadas em IA, que são definitivas e vinculantes","Seus dados serão vendidos a terceiros"],"explicacao":"Transparência e controle do usuário são princípios da norma."},{"id":3275,"materia":"ia","nivel":4,"enunciado":"Na Resolução CNJ 332/2020, os sistemas de IA usados como apoio à decisão judicial devem:","opcoes":["Permitir a supervisão do magistrado competente","Substituir o magistrado nos casos simples","Ser de uso obrigatório nas sentenças","Ficar fora de qualquer auditoria"],"explicacao":"O juiz mantém o controle sobre a decisão."},{"id":3276,"materia":"ia","nivel":4,"enunciado":"A 'janela de contexto' de um modelo de linguagem é:","opcoes":["A quantidade máxima de texto que o modelo considera de uma vez","O horário em que o modelo fica disponível para uso gratuito na internet","A tela onde o usuário digita a senha","A lista de sites bloqueados"],"explicacao":"Medida em tokens."},{"id":3277,"materia":"sust","nivel":0,"enunciado":"A sigla ODS significa:","opcoes":["Objetivos de Desenvolvimento Sustentável","Ordem de Defesa Social","Organização de Direitos Sociais","Orçamento de Despesa Setorial"],"explicacao":"São os 17 objetivos da Agenda 2030 da ONU."},{"id":3278,"materia":"sust","nivel":0,"enunciado":"Reaproveitar materiais para fabricar novos produtos é chamado de:","opcoes":["Reciclagem","Desmatamento","Assoreamento","Queimada"],"explicacao":"Reduz extração de recursos e geração de lixo."},{"id":3279,"materia":"sust","nivel":0,"enunciado":"O aquecimento global está ligado principalmente ao aumento na atmosfera de:","opcoes":["Gases de efeito estufa","Oxigênio puro","Vapor de mercúrio","Gás hélio"],"explicacao":"Como o CO₂ e o metano."},{"id":3280,"materia":"sust","nivel":0,"enunciado":"A sigla ESG, usada em sustentabilidade corporativa, refere-se a:","opcoes":["Ambiental, social e governança","Energia, segurança e gestão","Economia, serviço e garantia","Estado, sociedade e governo"],"explicacao":"Do inglês environmental, social and governance."},{"id":3281,"materia":"sust","nivel":1,"enunciado":"O ODS 12 da Agenda 2030 trata de:","opcoes":["Consumo e produção responsáveis","Saúde e bem-estar","Redução das desigualdades","Indústria e inovação"],"explicacao":"Inclui compras públicas sustentáveis."},{"id":3282,"materia":"sust","nivel":1,"enunciado":"O lema central da Agenda 2030 é:","opcoes":["Não deixar ninguém para trás","Crescer a qualquer custo","Primeiro a economia","Cada país por si"],"explicacao":"Busca alcançar todos os grupos sociais."},{"id":3283,"materia":"sust","nivel":1,"enunciado":"Greenwashing é a prática de:","opcoes":["Divulgar falsa imagem de sustentabilidade","Lavar resíduos antes da reciclagem","Plantar árvores em áreas urbanas","Usar energia solar em prédios"],"explicacao":"'Maquiagem verde' enganosa."},{"id":3284,"materia":"sust","nivel":2,"enunciado":"Na Lei 12.187/2009, mitigação significa:","opcoes":["Reduzir emissões de gases de efeito estufa e aumentar os sumidouros","Adaptar cidades às enchentes","Indenizar vítimas de desastres","Transferir indústrias poluentes para outros países com menos regras"],"explicacao":"Adaptação é reduzir a vulnerabilidade aos efeitos da mudança do clima."},{"id":3285,"materia":"sust","nivel":2,"enunciado":"Na Lei 12.187/2009, sumidouro é:","opcoes":["Processo ou atividade que remove gás de efeito estufa da atmosfera","Local apropriado para descarte de lixo hospitalar e de resíduos perigosos","Reservatório de água potável","Usina de energia nuclear"],"explicacao":"Ex.: florestas em crescimento."},{"id":3286,"materia":"sust","nivel":2,"enunciado":"É princípio da Política Nacional sobre Mudança do Clima:","opcoes":["Responsabilidades comuns, porém diferenciadas","Livre emissão para países em desenvolvimento","Proibição total de combustíveis fósseis","Exclusividade do setor privado"],"explicacao":"Também precaução, prevenção e participação cidadã."},{"id":3287,"materia":"sust","nivel":2,"enunciado":"A Lei 14.133/2021 permite margem de preferência para:","opcoes":["Bens reciclados, recicláveis ou biodegradáveis","Produtos importados de menor preço","Empresas com sede na capital","Fornecedores com mais tempo de mercado no setor"],"explicacao":"Art. 26, II da Lei 14.133/2021."},{"id":3288,"materia":"sust","nivel":2,"enunciado":"Pela Lei 14.133/2021, as licitações de obras e serviços de engenharia devem respeitar, entre outras normas:","opcoes":["As de disposição final adequada dos resíduos sólidos gerados","As de preferência a empresas estrangeiras com certificação internacional","As de dispensa de licenciamento ambiental","As de sigilo total dos projetos"],"explicacao":"Art. 45, I da Lei 14.133/2021."},{"id":3289,"materia":"sust","nivel":3,"enunciado":"Economia circular é o modelo que busca:","opcoes":["Manter materiais em uso pelo maior tempo possível, reduzindo o descarte","Extrair, produzir, usar e descartar rapidamente, sem reaproveitar os materiais","Concentrar a produção em um só país","Proibir a reciclagem de plásticos"],"explicacao":"Opõe-se à economia linear."},{"id":3290,"materia":"sust","nivel":3,"enunciado":"Pela CF/88, a exigência de estudo prévio de impacto ambiental se aplica a:","opcoes":["Obra ou atividade potencialmente causadora de significativa degradação","Qualquer construção residencial, mesmo as de pequeno porte em área urbana","Apenas obras federais","Somente atividades agrícolas"],"explicacao":"Art. 225, § 1º, IV; o estudo deve ser público."},{"id":3291,"materia":"sust","nivel":3,"enunciado":"Pela CF/88, quem pratica condutas lesivas ao meio ambiente fica sujeito a sanções penais e administrativas:","opcoes":["Independentemente da obrigação de reparar o dano","Somente se não reparar o dano","Apenas se for pessoa física","Só após condenação civil"],"explicacao":"Art. 225, § 3º; inclui pessoas jurídicas."},{"id":3292,"materia":"sust","nivel":3,"enunciado":"A Agenda Ambiental na Administração Pública (A3P) é um programa que estimula:","opcoes":["Órgãos públicos a adotar práticas de sustentabilidade","Empresas a pagar menos impostos","Municípios a ampliar áreas de mineração","A venda de créditos de carbono por servidores públicos federais"],"explicacao":"Coordenado pelo Ministério do Meio Ambiente."},{"id":3293,"materia":"sust","nivel":4,"enunciado":"A CF/88 declara patrimônio nacional, entre outros biomas:","opcoes":["Mata Atlântica e Pantanal Mato-Grossense","Cerrado e Caatinga","Pampa e Cerrado","Caatinga e Pampa"],"explicacao":"Art. 225, § 4º: também Floresta Amazônica, Serra do Mar e Zona Costeira."},{"id":3294,"materia":"sust","nivel":4,"enunciado":"Pela Lei 14.133/2021, a margem de preferência pode chegar, em regra, a:","opcoes":["10% sobre o preço dos demais bens e serviços","50% sobre o preço de referência fixado pelo órgão","2% sobre o preço","100% sobre o preço"],"explicacao":"Art. 26, § 1º; até 20% em caso de inovação tecnológica no país."},{"id":3295,"materia":"sust","nivel":4,"enunciado":"Os '5 Ps' da Agenda 2030 são:","opcoes":["Pessoas, planeta, prosperidade, paz e parcerias","Política, poder, produção, preço e povo","Paz, pátria, patrimônio, progresso e polícia","Planejamento, pessoal, prazo, produto, prova e preço"],"explicacao":"Áreas de importância que orientam os 17 ODS."},{"id":3296,"materia":"prev","nivel":0,"enunciado":"O órgão responsável por conceder aposentadorias do Regime Geral é o:","opcoes":["INSS","Banco Central","Ministério Público","Tribunal de Contas"],"explicacao":"Instituto Nacional do Seguro Social, autarquia federal."},{"id":3297,"materia":"prev","nivel":0,"enunciado":"RGPS é a sigla de:","opcoes":["Regime Geral de Previdência Social","Registro Geral de Pessoas e Serviços","Regime Gratuito de Proteção Social","Rede Geral de Pagamento Salarial"],"explicacao":"Regime dos trabalhadores da iniciativa privada."},{"id":3298,"materia":"prev","nivel":0,"enunciado":"A assistência social é prestada:","opcoes":["A quem dela necessitar, sem exigir contribuição","Somente a quem contribuiu por pelo menos 15 anos","Apenas a servidores públicos","Somente a maiores de 70 anos"],"explicacao":"Art. 203 da CF."},{"id":3299,"materia":"prev","nivel":1,"enunciado":"Pela Lei 8.213/1991, o produtor rural que trabalha em regime de economia familiar é segurado:","opcoes":["Especial","Facultativo","Contribuinte individual","Avulso"],"explicacao":"Pescador artesanal também é segurado especial."},{"id":3300,"materia":"prev","nivel":1,"enunciado":"Pela LC 150/2015, é empregado doméstico quem presta serviço à família por mais de:","opcoes":["2 dias por semana","1 dia por semana","4 dias por semana","15 dias por mês"],"explicacao":"Quem trabalha até 2 dias é diarista (contribuinte individual)."},{"id":3301,"materia":"prev","nivel":1,"enunciado":"O salário-família é devido ao segurado de baixa renda por filho de até:","opcoes":["14 anos, ou inválido de qualquer idade","18 anos, apenas","21 anos, apenas","7 anos, apenas"],"explicacao":"Também por enteado ou tutelado equiparado."},{"id":3302,"materia":"prev","nivel":1,"enunciado":"Na Lei 8.213/1991, reabilitação profissional e serviço social são:","opcoes":["Serviços da previdência social","Benefícios em dinheiro","Contribuições do empregador","Espécies de aposentadoria"],"explicacao":"Não são pagos em dinheiro."},{"id":3303,"materia":"prev","nivel":2,"enunciado":"Após a EC 103/2019, a contribuição do empregado ao RGPS tem alíquotas:","opcoes":["Progressivas, de 7,5% a 14%","Fixas de 20%","Fixas de 11%","Progressivas, de 1% a 3% conforme o risco"],"explicacao":"Incidem por faixa de salário de contribuição."},{"id":3304,"materia":"prev","nivel":2,"enunciado":"Pela Lei 8.212/1991, a contribuição da empresa sobre a remuneração dos empregados é, em regra, de:","opcoes":["20%","8%","11%","27,5%"],"explicacao":"Além do adicional para riscos ambientais do trabalho (1%, 2% ou 3%)."},{"id":3305,"materia":"prev","nivel":2,"enunciado":"A alíquota de contribuição do segurado facultativo no plano normal é de:","opcoes":["20%","11%","5%","8%"],"explicacao":"No plano simplificado é 11%; para baixa renda sem renda própria, 5%."},{"id":3306,"materia":"prev","nivel":2,"enunciado":"Pela CF, a aposentadoria no RGPS exige idade mínima de:","opcoes":["65 anos para homens e 62 anos para mulheres","60 anos para ambos","70 anos para homens e 65 anos para as mulheres","55 anos para ambos"],"explicacao":"Art. 201, § 7º, I, com redação da EC 103/2019."},{"id":3307,"materia":"prev","nivel":2,"enunciado":"Pela CF, é vedada a filiação ao RGPS, como segurado facultativo, de pessoa que:","opcoes":["Participe de regime próprio de previdência","Tenha mais de 60 anos","Seja estudante","Esteja desempregada"],"explicacao":"Art. 201, § 5º."},{"id":3308,"materia":"prev","nivel":2,"enunciado":"O BPC (benefício assistencial):","opcoes":["Não gera direito a pensão por morte","Gera pensão integral aos herdeiros","Exige 15 anos de contribuição","É pago apenas a servidores aposentados"],"explicacao":"Por ser assistencial, é personalíssimo."},{"id":3309,"materia":"prev","nivel":2,"enunciado":"No RGPS, é vedado receber cumulativamente:","opcoes":["Duas aposentadorias","Aposentadoria e salário-família","Pensão por morte e salário","Auxílio-acidente e salário"],"explicacao":"Art. 124 da Lei 8.213/1991."},{"id":3310,"materia":"prev","nivel":3,"enunciado":"Após a EC 103/2019, a pensão por morte corresponde a:","opcoes":["Cota familiar de 50% mais 10% por dependente, até 100%","100% do salário de benefício do falecido, para qualquer número de dependentes","Um salário mínimo fixo","70% mais 5% por dependente"],"explicacao":"Art. 23 da EC 103/2019."},{"id":3311,"materia":"prev","nivel":3,"enunciado":"A aposentadoria por incapacidade permanente decorrente de acidente do trabalho corresponde a:","opcoes":["100% do salário de benefício","60% do salário de benefício","50% do salário de benefício","Um salário mínimo"],"explicacao":"Nos demais casos, 60% + 2% por ano que exceder o tempo mínimo."},{"id":3312,"materia":"prev","nivel":3,"enunciado":"A pensão por morte será paga desde o óbito se requerida, pelos filhos menores de 16 anos, em até:","opcoes":["180 dias","90 dias","30 dias","1 ano"],"explicacao":"Para os demais dependentes, 90 dias (art. 74 da Lei 8.213/1991)."},{"id":3313,"materia":"prev","nivel":3,"enunciado":"Pela LOAS, o BPC deve ser revisto a cada:","opcoes":["2 anos","5 anos","6 meses","10 anos"],"explicacao":"Para avaliar a continuidade das condições que lhe deram origem."},{"id":3314,"materia":"prev","nivel":3,"enunciado":"A assistência social é organizada, pela LOAS, em um sistema descentralizado e participativo chamado:","opcoes":["SUAS","SUS","SINARM","SISNAMA"],"explicacao":"Sistema Único de Assistência Social."},{"id":3315,"materia":"prev","nivel":4,"enunciado":"A aposentadoria do trabalhador rural no RGPS exige idade mínima de:","opcoes":["60 anos para homens e 55 para mulheres","65 anos para homens e 62 para mulheres","55 anos para ambos","50 anos para homens e 45 para mulheres"],"explicacao":"Redução de 5 anos (art. 201, § 7º, II)."},{"id":3316,"materia":"prev","nivel":4,"enunciado":"O regime próprio de previdência dos servidores tem, pela CF, caráter:","opcoes":["Contributivo e solidário","Gratuito e assistencial","Facultativo e privado","Indenizatório e eventual"],"explicacao":"Art. 40 da CF."},{"id":3317,"materia":"pciv","nivel":2,"enunciado":"A denunciação da lide serve, em regra, para:","opcoes":["Exercer direito de regresso contra quem deve indenizar a parte que perder","Retirar o réu do processo e colocar outra pessoa em seu lugar como parte","Pedir prova pericial","Trocar o juiz da causa"],"explicacao":"Art. 125 do CPC."},{"id":3318,"materia":"pciv","nivel":3,"enunciado":"Pelo CPC, a revelia NÃO produz o efeito de presunção de veracidade quando:","opcoes":["O litígio versar sobre direitos indisponíveis","O réu for pessoa física","A ação for de cobrança","O autor tiver advogado"],"explicacao":"Art. 345, II do CPC."},{"id":3319,"materia":"pciv","nivel":3,"enunciado":"Na Justiça Federal, cabe ao TRF julgar recursos contra decisões de juízes estaduais quando estes:","opcoes":["Exercem competência federal delegada","Julgam crimes comuns","Julgam causas de família","Atuam em juizados especiais estaduais da Fazenda Pública"],"explicacao":"Art. 109, § 4º da CF."},{"id":3320,"materia":"adm","nivel":2,"enunciado":"Pela Lei 8.112/1990, a licença para capacitação pode ser concedida, após cada quinquênio de efetivo exercício, por até:","opcoes":["3 meses","6 meses","1 mês","1 ano"],"explicacao":"Art. 87 da Lei 8.112/1990."},{"id":3321,"materia":"const","nivel":2,"enunciado":"Os Tribunais Regionais Federais compõem-se de, no mínimo:","opcoes":["7 juízes","11 juízes","15 juízes","27 juízes"],"explicacao":"Art. 107 da CF."},{"id":3322,"materia":"const","nivel":2,"enunciado":"O TRF da 4ª Região tem jurisdição sobre os estados do:","opcoes":["Rio Grande do Sul, Santa Catarina e Paraná","São Paulo e Mato Grosso do Sul","Rio de Janeiro, Espírito Santo e Minas Gerais","Minas Gerais"],"explicacao":"Sede em Porto Alegre."},{"id":3323,"materia":"const","nivel":3,"enunciado":"Nos crimes políticos julgados pela Justiça Federal, o recurso cabível contra a sentença é:","opcoes":["Recurso ordinário ao STF","Apelação ao TRF","Recurso especial ao STJ, por violação a lei federal","Agravo ao CNJ"],"explicacao":"Art. 102, II, 'b' da CF."},{"id":3324,"materia":"trib","nivel":2,"enunciado":"O IBS, criado pela reforma tributária, é administrado pelo:","opcoes":["Comitê Gestor do IBS","Ministério da Fazenda","Banco Central","Conselho Nacional de Justiça"],"explicacao":"Reúne estados, DF e municípios."},{"id":3325,"materia":"trib","nivel":3,"enunciado":"Pelo cronograma da reforma tributária, ICMS e ISS serão extintos em:","opcoes":["2033","2026","2027","2040"],"explicacao":"A transição desses tributos ocorre de 2029 a 2032."},{"id":3326,"materia":"trib","nivel":3,"enunciado":"Pela EC 132/2023, o Imposto Seletivo:","opcoes":["Não incide sobre exportações","Incide sobre todos os serviços","Substitui o imposto de renda","É de competência municipal"],"explicacao":"Também não incide sobre telecomunicações e energia elétrica."},{"id":3327,"materia":"trib","nivel":3,"enunciado":"Pela reforma tributária, os produtos da Cesta Básica Nacional de Alimentos terão:","opcoes":["Alíquota zero de IBS e CBS","Alíquota dobrada","Cobrança do Imposto Seletivo","Isenção apenas no Nordeste"],"explicacao":"Prevista na EC 132/2023 e na LC 214/2025."},{"id":3328,"materia":"gest","nivel":2,"enunciado":"Na gestão de riscos, o nível de risco costuma ser avaliado pela combinação de:","opcoes":["Probabilidade e impacto","Custo e prazo","Receita e despesa","Missão e visão"],"explicacao":"Conforme a ISO 31000."},{"id":3329,"materia":"gest","nivel":3,"enunciado":"O apetite a risco de uma organização é:","opcoes":["O nível de risco que ela está disposta a aceitar para atingir seus objetivos","A soma das perdas do ano anterior","O número de riscos identificados","O valor do seguro contratado contra perdas financeiras, operacionais e de imagem no ano"],"explicacao":"Orienta a resposta aos riscos."},{"id":3330,"materia":"pcd","nivel":1,"enunciado":"Na LBI, as barreiras urbanísticas são aquelas existentes:","opcoes":["Nas vias e nos espaços públicos e privados abertos ao público","Nos sistemas de informática e nos sites","Nas atitudes e comportamentos das pessoas","Apenas no interior das residências"],"explicacao":"Art. 3º, IV, 'a' da Lei 13.146/2015."},{"id":3331,"materia":"pcd","nivel":1,"enunciado":"Pela LBI, o atendente pessoal é a pessoa que:","opcoes":["Presta cuidados básicos e essenciais à pessoa com deficiência no dia a dia","Representa a pessoa com deficiência em todas as ações judiciais e administrativas","Faz a perícia médica no INSS","Fiscaliza a acessibilidade de prédios públicos e privados"],"explicacao":"Art. 3º, XII; não inclui técnicas de profissões regulamentadas."},{"id":3332,"materia":"prev","nivel":1,"enunciado":"No RGPS, o MEI (microempreendedor individual) é segurado na categoria de:","opcoes":["Contribuinte individual","Empregado","Segurado especial","Trabalhador avulso"],"explicacao":"Contribui com alíquota reduzida de 5%."},{"id":3333,"materia":"prev","nivel":2,"enunciado":"O trabalhador avulso presta serviço a várias empresas, sem vínculo de emprego, com intermediação:","opcoes":["Do sindicato ou do órgão gestor de mão de obra","De agência de empregos privada contratada pela empresa","Do próprio INSS","Da Justiça do Trabalho"],"explicacao":"Ex.: trabalhadores portuários."},{"id":3334,"materia":"prev","nivel":3,"enunciado":"O segurado empregado que deixa de contribuir mantém a qualidade de segurado, em regra, por até:","opcoes":["12 meses","6 meses","36 meses","3 meses"],"explicacao":"Prorrogável para 24 meses com mais de 120 contribuições e por mais 12 se desempregado."},{"id":3335,"materia":"ia","nivel":1,"enunciado":"Nos modelos de linguagem, token é:","opcoes":["Pequeno pedaço de texto que o modelo processa","Senha de acesso ao sistema","Moeda digital usada para pagar o serviço por assinatura","Arquivo de backup do modelo"],"explicacao":"Prompts e respostas são medidos em tokens."},{"id":3336,"materia":"sust","nivel":1,"enunciado":"O ODS 7 da Agenda 2030 trata de:","opcoes":["Energia limpa e acessível","Vida terrestre","Trabalho decente e crescimento econômico","Educação de qualidade"],"explicacao":"Inclui ampliar a participação de energias renováveis."},{"id":3337,"materia":"adm","nivel":2,"enunciado":"Pela Lei 11.416/2006, cada carreira do Judiciário da União está organizada nas classes:","opcoes":["A, B e C","I, II, III e IV","Júnior, pleno e sênior","Inicial e final"],"explicacao":"Cada classe tem padrões, e o servidor progride por mérito e tempo."},{"id":3338,"materia":"pcd","nivel":2,"enunciado":"Pela Lei 10.098/2000, nos edifícios públicos ou de uso coletivo, pelo menos um dos acessos ao interior deve estar:","opcoes":["Livre de barreiras e de obstáculos à acessibilidade","Equipado com catraca eletrônica de controle de entrada","Reservado ao uso exclusivo de autoridades","Fechado fora do horário de expediente"],"explicacao":"Art. 11, parágrafo único, II da Lei 10.098/2000."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('prev','pcd','ia','sust') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
